def solve(inp):
    h,w=len(inp),len(inp[0])
    cells={(r,c) for r in range(h) for c in range(w) if inp[r][c]==8}
    ORI={('U','L'):2,('L','D'):3,('U','R'):4,('D','R'):5}
    D={'U':(-1,0),'D':(1,0),'L':(0,-1),'R':(0,1)}
    def options(p):
        r,c=p; opts=[]
        s=[(r,c),(r,c+1),(r+1,c),(r+1,c+1)]
        if all(q in cells for q in s): opts.append((s,1))
        for corner in s:
            cr,cc=corner
            for a,b in ORI:
                s2=[(cr,cc),(cr+D[a][0],cc+D[a][1]),(cr+D[b][0],cc+D[b][1])]
                if p in s2 and all(q in cells for q in s2): opts.append((s2,ORI[(a,b)]))
        return opts
    order=sorted(cells); used=set()
    placed=[]
    def bt():
        rem=[q for q in order if q not in used]
        if not rem: return True
        for s2,col in options(rem[0]):
            used.update(s2); placed.append((s2,col))
            if bt(): return True
            used.difference_update(s2); placed.pop()
        return False
    assert bt(), "no tiling"
    res=[[0]*w for _ in range(h)]
    for s2,col in placed:
        for (r,c) in s2: res[r][c]=col
    return res

